```yaml
name: Publish Connectors Prerelease Command

on:
  issue_comment:
    types: [created]

jobs:
  dispatch:
    name: Dispatch Prerelease
    runs-on: ubuntu-latest
    if: github.event.issue.pull_request && startsWith(github.event.comment.body, '/publish-connectors-prerelease')
    steps:
      - name: Get PR Info
        id: pr_info
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = context.issue.number;
            const response = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });
            const sha = response.data.head.sha;
            const shortSha = sha.substring(0, 10);
            core.setOutput('sha', sha);
            core.setOutput('short_sha', shortSha);
            core.setOutput('pr_number', prNumber);

      - name: Post Start Comment
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          pr-number: ${{ steps.pr_info.outputs.pr_number }}
          comment-tag: prerelease-start
          message: |
            🚀 **Prerelease Build Started**

            Publishing pre-release connectors for PR #${{ steps.pr_info.outputs.pr_number }}.

            **Image Tag Format:** `{version}-dev.${{ steps.pr_info.outputs.short_sha }}`

            Please wait for the completion comment.

      - name: Call Publish Connectors Workflow
        id: call_publish
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = ${{ steps.pr_info.outputs.pr_number }};
            const sha = '${{ steps.pr_info.outputs.sha }}';

            try {
              const response = await github.rest.actions.createWorkflowDispatch({
                owner: context.repo.owner,
                repo: context.repo.repo,
                workflow_id: 'publish_connectors.yml',
                ref: sha,
                inputs: {
                  'release-type': 'pre-release',
                  'pr-number': prNumber.toString()
                }
              });
              core.info(`Workflow dispatch initiated: ${response.status}`);
            } catch (error) {
              core.setFailed(`Failed to dispatch workflow: ${error.message}`);
            }

      - name: Wait for Workflow Completion
        uses: lewagon/wait-on-check-action@v1.3.4
        with:
          ref: ${{ steps.pr_info.outputs.sha }}
          check-name: 'Publish Connectors'
          repo-token: ${{ secrets.GITHUB_TOKEN }}
          wait-interval: 10
          wait-fail-timeout-seconds: 3600

      - name: Get Workflow Run Status
        id: get_status
        uses: actions/github-script@v7
        with:
          script: |
            const prNumber = ${{ steps.pr_info.outputs.pr_number }};
            const sha = '${{ steps.pr_info.outputs.sha }}';

            // Find the workflow run for publish_connectors.yml on this SHA
            const runs = await github.rest.actions.listWorkflowRunsForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              workflow_id: 'publish_connectors.yml',
              head_sha: sha,
              status: 'completed'
            });

            if (runs.data.workflow_runs.length === 0) {
              throw new Error('No completed workflow runs found');
            }

            // Get the most recent run
            const run = runs.data.workflow_runs[0];
            core.setOutput('status', run.conclusion);
            core.setOutput('html_url', run.html_url);

      - name: Post Completion Comment
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          pr-number: ${{ steps.pr_info.outputs.pr_number }}
          comment-tag: prerelease-completion
          message: |
            ${{ steps.get_status.outputs.status == 'success' && '✅ **Prerelease Build Successful**' || '❌ **Prerelease Build Failed**' }}

            ${{ steps.get_status.outputs.status == 'success' && 'Connectors have been published with tag suffix `-dev.${{ steps.pr_info.outputs.short_sha }}`.' || 'The build failed. Please check the logs.' }}

            [View Workflow Run](${{ steps.get_status.outputs.html_url }})
